use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node's `with` clause grants. Checked before every fetch so that
/// an out-of-scope request is recorded as a failure rather than trapping the run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the lowercase host from an http(s) URL. Returns `None` for anything
/// that does not parse to a plain DNS-style host.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(|c| c == '/' || c == '?' || c == '#').next()?;
    // Drop any userinfo: take what follows the last '@'.
    let host_port = authority.rsplit('@').next()?;
    if host_port.contains('[') {
        return None; // IPv6 literals are never on the allowlist.
    }
    // Drop any port.
    let host = host_port.split(':').next()?;
    if host.is_empty()
        || !host
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '.')
    {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {}
                _ => {
                    failures.push(FetchFailure {
                        url,
                        error: "host not in allowlist".to_string(),
                    });
                    continue;
                }
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
